  'Choose a field to opt-in to {name}. For example, you might only wish to subscribe users if they provide a value for a field of your choice - commonly, an Agree field.' => 'Wähle ein Feld zum Eintragen in {name}. Du möchtest vielleicht Nutzer nur dann abonnieren, wenn sie einen Wert für ein von dir gewähltes Feld angeben - üblicherweise ein Zustimmungsfeld.',
