  'Choose the minimum OOPSpam score that should be treated as spam. OOPSpam recommends `3` and higher.' => 'Wählen Sie den Mindestwert für den OOPSpam-Score, ab dem eine Nachricht als Spam behandelt werden soll. OOPSpam empfiehlt einen Wert von `3` oder höher.',
