  'Choose whether the limit applies to all submissions for this form, each IP address, or each logged-in user. When limiting all submissions, the form closes once the limit is reached.' => 'Wählen Sie aus, ob die Begrenzung für alle Übermittlungen dieses Formulars, für jede IP-Adresse oder für jeden angemeldeten Benutzer gelten soll. Bei einer Begrenzung aller Übermittlungen wird das Formular geschlossen, sobald das Limit erreicht ist.',
  'Choose whether the progress bar should reflect completed progress or current page position.' => 'Wählen Sie aus, ob der Fortschrittsbalken den erreichten Fortschritt oder die aktuelle Seitenposition anzeigen soll.',
  'Choose whether the state/province field should always be a text input, or use a dropdown when subdivision data is available for the selected country.' => 'Legen Sie fest, ob das Feld „Bundesland/Provinz“ immer als Texteingabefeld angezeigt werden soll oder ob eine Auswahlliste verwendet werden soll, wenn für das ausgewählte Land Daten zu Untereinheiten verfügbar sind.',
  'Choose whether to collect a single date/time or a start/end range.' => 'Wählen Sie aus, ob Sie ein einzelnes Datum/eine einzelne Uhrzeit oder einen Start- und Endzeitraum erfassen möchten.',
  'Choose whether to evaluate this rule on every page submission or only when the form is fully submitted.' => 'Legen Sie fest, ob diese Regel bei jeder Seitenübermittlung oder erst dann ausgewertet werden soll, wenn das Formular vollständig übermittelt wurde.',
  'Choose whether to redirect to a URL or a Craft entry when this rule matches.' => 'Legen Sie fest, ob bei Übereinstimmung mit dieser Regel eine Weiterleitung zu einer URL oder zu einem Craft-Eintrag erfolgen soll.',
  'Choose whether Turnstile should run on page load or wait until Formie triggers it during submit. `Run On Submit` may show no visible widget until submit.' => 'Legen Sie fest, ob „Turnstile“ beim Laden der Seite ausgeführt werden soll oder ob gewartet werden soll, bis Formie es beim Absenden auslöst. Bei der Option „Run On Submit“ wird möglicherweise bis zum Absenden kein Widget angezeigt.',
  'Choose which Craft field adapter should power this Formie field. This cannot be changed later.' => 'Wählen Sie aus, welcher Craft-Feldadapter dieses Formie-Feld mit Daten versorgen soll. Diese Auswahl kann später nicht mehr geändert werden.',
  'Choose which days of the week should be available.' => 'Wählen Sie aus, an welchen Wochentagen der Dienst verfügbar sein soll.',
  'Choose which link types can be submitted from the front-end form.' => 'Wählen Sie aus, welche Linktypen über das Frontend-Formular übermittelt werden können.',
