  'Controls when a visible widget is shown. Some widget modes configured in Cloudflare may still remain invisible.' => 'Steuert, wann ein sichtbares Widget angezeigt wird. Einige in Cloudflare konfigurierte Widget-Modi bleiben möglicherweise weiterhin unsichtbar.',
  'Control the order integrations run in, whether they execute immediately or via the queue, and when email notifications are sent.' => 'Legen Sie fest, in welcher Reihenfolge die Integrationen ausgeführt werden, ob sie sofort oder über die Warteschlange ausgeführt werden und wann E-Mail-Benachrichtigungen versendet werden.',
  'Control whether captcha integrations are enabled by default on new forms and stencils. Inherit uses each integration’s global enabled state.' => 'Legen Sie fest, ob Captcha-Integrationen in neuen Formularen und Vorlagen standardmäßig aktiviert sind. Bei der Option „Übernehmen“ wird der globale Aktivierungsstatus der jeweiligen Integration übernommen.',
  'Control whether captcha integrations are enabled by default on new forms in this group. Inherit uses the global default.' => 'Legen Sie fest, ob Captcha-Integrationen in neuen Formularen dieser Gruppe standardmäßig aktiviert sind. Bei der Option „Übernehmen“ wird die globale Standardeinstellung verwendet.',
