  'Enable this option to send nominated email addresses an alert email when an integration cannot be triggered.' => 'Aktivieren Sie diese Option, um eine Benachrichtigungs-E-Mail an die angegebenen E-Mail-Adressen zu senden, wenn eine Integration nicht ausgelöst werden kann.',
