  'Ensure you understand the implications of disabling Formie‘s JavaScript. Read the [docs](https://verbb.io/craft-plugins/formie/docs/developers/front-end-js) for more information.' => 'Stelle sicher, dass du die Auswirkungen der Deaktivierung von Formies JavaScript verstehst. Lies die [Dokumentation](https://verbb.io/craft-plugins/formie/docs/developers/front-end-js) für weitere Informationen.',
  'Enter a description for the product as shown in checkout.' => 'Geben Sie eine Beschreibung für das Produkt ein, wie sie an der Kasse angezeigt wird.',
  'Enter a description for the subscription. It appears against the GoCardless subscription and in customer communications.' => 'Geben Sie eine Beschreibung für das Abonnement ein. Diese wird neben dem GoCardless-Abonnement sowie in der Kundenkommunikation angezeigt.',
  'Enter a description for the subscription. This will only be shown in Stripe.' => 'Geben Sie eine Beschreibung für das Abonnement ein. Diese wird ausschließlich in Stripe angezeigt.',
  'Enter a description for this payment, to appear against the transaction in your Mollie account, and on the payment receipt sent to the customer.' => 'Geben Sie eine Beschreibung für diese Zahlung ein, die in Ihrem Mollie-Konto neben der Transaktion sowie auf der Zahlungsbestätigung erscheint, die an den Kunden gesendet wird.',
  'Enter a description for this payment, to appear against the transaction in your Stripe account, and on the payment receipt sent to the customer.' => 'Geben Sie eine Beschreibung für diese Zahlung ein, die in Ihrem Stripe-Konto neben der Transaktion sowie auf der Zahlungsbestätigung erscheint, die an den Kunden gesendet wird.',
  'Enter a description for this payment. It appears against the GoCardless payment and in customer communications.' => 'Geben Sie eine Beschreibung für diese Zahlung ein. Diese wird bei der GoCardless-Zahlung sowie in der Kundenkommunikation angezeigt.',
  'Enter a formula to test.' => 'Geben Sie eine Formel ein, die Sie testen möchten.',
  'Enter an optional offset for today‘s date.' => 'Geben Sie einen optionalen Versatz für das heutige Datum ein.',
  'Enter any additional email addresses to receive failed integration alerts. These recipients do not need to be Craft users.' => 'Geben Sie hier weitere E-Mail-Adressen ein, an die Benachrichtigungen über fehlgeschlagene Integrationen gesendet werden sollen. Diese Empfänger müssen keine Craft-Nutzer sein.',
  'Enter any additional email addresses to receive failed notification alerts. These recipients do not need to be Craft users.' => 'Geben Sie hier weitere E-Mail-Adressen ein, an die Benachrichtigungen über fehlgeschlagene Vorgänge gesendet werden sollen. Diese Empfänger müssen keine Craft-Nutzer sein.',
  'Enter a valid subscription payment limit.' => 'Geben Sie ein gültiges Zahlungslimit für das Abonnement ein.',
  'Enter a valid subscription setup fee.' => 'Geben Sie eine gültige Einrichtungsgebühr für das Abonnement ein.',
  'Enter formatted content to be rendered for this field.' => 'Geben Sie den formatierten Inhalt ein, der für dieses Feld angezeigt werden soll.',
  'Enter HTML or Twig content to be rendered for this field.' => 'Gib HTML- oder Twig-Inhalt ein, der für dieses Feld gerendert werden soll.',
  'Entering the query parameter to populate the value of the field when it loads.' => 'Eingabe des Abfrageparameters, um den Wert des Feldes beim Laden zu befüllen.',
  'Enter one domain per line, such as `mailinator.com` or `tempmail.net`.' => 'Geben Sie pro Zeile eine Domain ein, zum Beispiel `mailinator.com` oder `tempmail.net`.',
  'Enterprise Key Type' => 'Unternehmensschlüsseltyp',
  'Enter the chat ID for the channel, group, or user. This must be obtained manually via the Telegram API or logs.' => 'Geben Sie die Chat-ID des Kanals, der Gruppe oder des Nutzers ein. Diese muss manuell über die Telegram-API oder aus den Protokollen abgerufen werden.',
  'Enter the email the payment receipt should be delivered to.' => 'Geben Sie die E-Mail-Adresse ein, an die die Zahlungsbestätigung gesendet werden soll.',
  'Enter the format for uploaded files to be renamed as. Do not include the extension.' => 'Geben Sie das Format ein, nach dem hochgeladene Dateien umbenannt werden sollen. Geben Sie die Dateiendung nicht an.',
  'Enter the format of the auto-generated submission titles. If left blank, the date/time of submission will be used.' => 'Gib das Format der automatisch generierten Übermittlungstitel ein. Wenn leer gelassen, wird das Datum/die Uhrzeit der Übermittlung verwendet.',
  'Enter the GUID of a valid systemuser to impersonate.' => 'Geben Sie die GUID eines gültigen Systembenutzers ein, dessen Identität Sie annehmen möchten.',
  'Enter the label for the toggle checkbox field.' => 'Geben Sie das Label für das Umschaltkästchenfeld ein.',
  'Enter the minimum score needed to pass the hCaptcha test.' => 'Geben Sie die Mindestpunktzahl ein, die zum Bestehen des hCaptcha-Tests erforderlich ist.',
  'Enter the minimum score needed to pass the reCAPTCHA test.' => 'Gib die erforderliche Mindestpunktzahl ein, um den reCAPTCHA-Test zu bestehen.',
  'Enter the name of the cookie to use as the value of this field.' => 'Geben Sie den Namen des Cookies ein, der als Wert dieses Felds verwendet werden soll.',
  'Enter the SharpSpring native form endpoint ID used for payload sync.' => 'Geben Sie die ID des nativen SharpSpring-Formular-Endpunkts ein, der für die Synchronisierung der Nutzdaten verwendet wird.',
  'Enter the URL that will be triggered when a submission is made.' => 'Geben Sie die URL ein, die bei einer Übermittlung aufgerufen werden soll.',
  'Enter the website key for the selected reCAPTCHA mode. For reCAPTCHA Enterprise, this must be a website key whose type matches the selected Enterprise Key Type.' => 'Geben Sie den Website-Schlüssel für den ausgewählten reCAPTCHA-Modus ein. Bei reCAPTCHA Enterprise muss es sich um einen Website-Schlüssel handeln, dessen Typ mit dem ausgewählten Enterprise-Schlüsseltyp übereinstimmt.',
