  'Protect your business from bots and spam while ensuring 100% data privacy compliance. No puzzles, no tracking – just invisible security that works. Find out more via [captcha.eu](https://www.captcha.eu/).' => 'Schützen Sie Ihr Unternehmen vor Bots und Spam und gewährleisten Sie gleichzeitig die 100-prozentige Einhaltung der Datenschutzbestimmungen. Keine Rätsel, kein Tracking – einfach unsichtbare Sicherheit, die funktioniert. Erfahren Sie mehr unter [captcha.eu](https://www.captcha.eu/).',
  'Provide additional elements to be shown in tabs when building the form.' => 'Zusätzliche Elemente bereitstellen, die beim Erstellen des Formulars in Registerkarten angezeigt werden sollen.',
  'Provide a meaningful action name sent with Enterprise score and policy-based challenge requests. This should match the action thresholds or reporting you want to use in Google Cloud.' => 'Geben Sie einen aussagekräftigen Aktionsnamen an, der zusammen mit dem Enterprise-Score und richtlinienbasierten Anforderungsanfragen übermittelt wird. Dieser sollte mit den Aktionsschwellenwerten oder der Berichterstellung übereinstimmen, die Sie in Google Cloud verwenden möchten.',
  'Provide an amount for the transaction. This can be either a fixed value, or derived from a field.' => 'Geben Sie einen Betrag für die Transaktion an. Dies kann entweder ein fester Wert sein oder aus einem Feld abgeleitet werden.',
  'Provide an explanation for the correct answer, shown when displaying quiz results.' => 'Geben Sie eine Erklärung für die richtige Antwort an, die bei der Anzeige der Quiz-Ergebnisse angezeigt wird.',
