  'Provide default analytics events for every page. Individual pages can override these in the Tracking tab when editing page buttons.' => 'Stellen Sie für jede Seite Standard-Analyseereignisse bereit. Diese können auf einzelnen Seiten auf der Registerkarte „Tracking“ beim Bearbeiten der Seitenschaltflächen überschrieben werden.',
