  'Select a user to be the default author for the created event. An event must always have an author.' => 'Wählen Sie einen Benutzer aus, der als Standardautor für das erstellte Ereignis dienen soll. Ein Ereignis muss immer einen Autor haben.',
  'Select a user to be the default author for the created product.' => 'Wählen Sie einen Benutzer aus, der als Standardautor für das erstellte Produkt dienen soll.',
