  'Select the fields you want to use to check for existing elements. Formie will look for existing elements with the attributes chosen and the values provided in the submission.' => 'Wähle die Felder aus, die du verwenden möchtest, um nach vorhandenen Elementen zu suchen. Formie wird nach vorhandenen Elementen mit den gewählten Attributen und den in der Einreichung bereitgestellten Werten suchen.',
