  'Select the format for the dropdown option value.' => 'Wählen Sie das Format für den Wert der Dropdown-Option aus.',
  'Select the forms you wish to migrate from {source}. This will migrate all fields within the form, all settings (where applicable), notifications, and any {entryType}. Depending on how many entries the selected forms have, this could take some time.' => 'Wählen Sie die Formulare aus, die Sie aus {source} migrieren möchten. Dabei werden alle Felder des Formulars, alle Einstellungen (sofern vorhanden), Benachrichtigungen und alle {entryType} migriert. Je nachdem, wie viele Einträge die ausgewählten Formulare enthalten, kann dies einige Zeit in Anspruch nehmen.',
  'Select the HTTP Method used to send data.' => 'Wählen Sie die HTTP-Methode aus, die zum Senden der Daten verwendet werden soll.',
  'Select the notification you‘d like to send.' => 'Wählen Sie die Benachrichtigung aus, die Sie senden möchten.',
  'Select the position of the page progress indicator in the form.' => 'Wähle die Position des Seitenfortschrittsindikators im Formular.',
  'Select the reCAPTCHA Enterprise website key type to use. Google Enterprise website keys are mode-specific, so each type needs its own matching website key.' => 'Wählen Sie den zu verwendenden reCAPTCHA Enterprise-Website-Schlüsseltyp aus. Google Enterprise-Website-Schlüssel sind modusspezifisch, daher benötigt jeder Typ einen eigenen, passenden Website-Schlüssel.',
