  'Select the size for Turnstile to use. Cloudflare only applies this to Managed and Non-interactive widgets.' => 'Wählen Sie die Größe für „Turnstile“ aus. Cloudflare wendet diese Einstellung nur auf verwaltete und nicht-interaktive Widgets an.',
