  'Set a server-resolved default using Craft object template syntax. Submitted values are ignored for this field. See [object templates](https://craftcms.com/docs/5.x/system/object-templates.html). Available: `{form.handle}`, `{form.title}`, `{currentUser.email}`, `{site.handle}`, `{request.param.myParam}`, `{submission.id}`.' => 'Legen Sie einen vom Server aufgelösten Standardwert mithilfe der Craft-Objektvorlagensyntax fest. Eingereichte Werte werden für dieses Feld ignoriert. Siehe [Objektvorlagen](https://craftcms.com/docs/5.x/system/object-templates.html). Verfügbar: `{form.handle}`, `{form.title}`, `{currentUser.email}`, `{site.handle}`, `{request.param.myParam}`, `{submission.id}`.',
  'Set a specific web API version to use with {name} Web API requests.' => 'Legen Sie eine bestimmte Web-API-Version fest, die bei {name}-Web-API-Anfragen verwendet werden soll.',
