  'Set defaults applied when a new notification is created. Leave fields empty to inherit Formie’s built-in behaviour.' => 'Legen Sie die Standardwerte fest, die beim Erstellen einer neuen Benachrichtigung übernommen werden. Lassen Sie die Felder leer, um das standardmäßige Verhalten von Formie zu übernehmen.',
  'Set defaults applied when a new notification is created on forms in this group. Leave fields empty to inherit global defaults.' => 'Legen Sie die Standardwerte fest, die beim Erstellen einer neuen Benachrichtigung in Formularen dieser Gruppe angewendet werden. Lassen Sie die Felder leer, um die globalen Standardwerte zu übernehmen.',
