  'Set the number of decimal points to format the field value.' => 'Legen Sie die Anzahl der Dezimalstellen fest, um den Feldwert zu formatieren.',
  'Set the number of seconds to set the timeout for Ajax-based forms. This should only be adjusted for forms where a large timeout is expected, such as heavy use of file upload fields. This is also only applicable when using the Theme JS. Default to 10 seconds.' => 'Legen Sie die Anzahl der Sekunden fest, um das Timeout für auf Ajax basierende Formulare einzustellen. Dies sollte nur bei Formularen angepasst werden, bei denen ein grosses Timeout erwartet wird, wie zum Beispiel bei intensiver Nutzung von Datei-Upload-Feldern. Dies gilt auch nur bei Verwendung des Theme JS. Standardmässig 10 Sekunden.',
  'Set the OAuth redirect URI if you need to change it from the default action URL. Use this when registering your app with third-party providers.' => 'Legen Sie die OAuth-Weiterleitungs-URI fest, falls Sie die Standard-Aktions-URL ändern müssen. Verwenden Sie diese bei der Registrierung Ihrer App bei Drittanbietern.',
