  'Set the [HTML autocomplete attribute](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/autocomplete) for this field’s input. Use “Default (browser)” to omit the attribute, or add sectioned values such as `billing email` via Input Attributes in Advanced.' => 'Legen Sie das [HTML-Attribut „autocomplete“](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/autocomplete) für das Eingabefeld dieses Feldes fest. Verwenden Sie „Standard (Browser)“, um das Attribut wegzulassen, oder fügen Sie unter „Erweiterte Einstellungen“ im Bereich „Eingabeattribute“ segmentierte Werte wie z. B. `Rechnungs-E-Mail` hinzu.',
