  'The directory must be empty for files to be copied.' => 'Das Verzeichnis muss leer sein, damit Dateien kopiert werden können.',
  'The email address for the notification email "sender" header, for advanced usage. Leave empty to use the "From Email".' => 'Die E-Mail-Adresse für den „Absender“-Header der Benachrichtigungs-E-Mail, für fortgeschrittene Anwendungen. Lassen Sie das Feld leer, um die „Absender-E-Mail“ zu verwenden.',
  'The email address the notification email will be sent from. Leave empty to use the default email address for your site.' => 'Die E-Mail-Adresse, von der aus die Benachrichtigungs-E-Mail versendet wird. Lassen Sie das Feld leer, um die Standard-E-Mail-Adresse Ihrer Website zu verwenden.',
