  'The line item description shown in Stripe for the setup fee. Defaults to “Setup fee”.' => 'Die in Stripe angezeigte Positionsbezeichnung für die Einrichtungsgebühr. Standardmäßig lautet sie „Einrichtungsgebühr“.',
  'The maximum age of an incomplete submission in days before it is deleted in garbage collection. Set to 0 to disable automatic deletion.' => 'Das maximale Alter einer unvollständigen Einreichung in Tagen, bevor sie bei der Garbage Collection gelöscht wird. Auf 0 setzen, um die automatische Löschung zu deaktivieren.',
