  'The number of days to keep sent notifications before they are deleted permanently. Set to 0 to disable automatic deletion.' => 'Die Anzahl der Tage, die gesendete Benachrichtigungen aufbewahrt werden, bevor sie dauerhaft gelöscht werden. Auf 0 setzen, um die automatische Löschung zu deaktivieren.',
