  'This field uses a legacy preview template. Replace it with `defineFormBuilderPreviewSchema()` to restore builder previews.' => 'Dieses Feld verwendet eine veraltete Vorschauvorlage. Ersetzen Sie diese durch `defineFormBuilderPreviewSchema()`, um die Builder-Vorschauen wiederherzustellen.',
