  'Weighted Score' => 'Gewichtete Punktzahl',
  'We only collect data specifically for your form, nothing else related to your install. We collect:' => 'Wir sammeln nur Daten, die speziell für Ihr Formular sind, nichts anderes, was mit Ihrer Installation zusammenhängt. Wir sammeln:',
  'We use Craft‘s [garbage collection]({link}) mechanism to remove submissions, so this may not always be actioned immediately.' => 'Wir nutzen den [Garbage-Collection]({link})-Mechanismus von Craft, um Einsendungen zu entfernen, daher erfolgt dies möglicherweise nicht immer sofort.',
  'We use Craft‘s [garbage collection]({link}) mechanism to remove uploaded assets, so this may not always be actioned immediately.' => 'Wir nutzen den [Garbage Collection]({link})-Mechanismus von Craft, um hochgeladene Assets zu entfernen, daher erfolgt dies möglicherweise nicht immer sofort.',
  'We were unable to finalize your payment-backed submission. Please try again or contact support.' => 'Wir konnten Ihre zahlungsgebundene Einreichung nicht abschließen. Bitte versuchen Sie es erneut oder wenden Sie sich an den Support.',
  'We were unable to verify your payment. Please try again or contact support.' => 'Wir konnten Ihre Zahlung nicht überprüfen. Bitte versuchen Sie es erneut oder wenden Sie sich an den Support.',
  'What this form group will be called in the control panel.' => 'Wie diese Formulargruppe im Kontrollpanel heißen soll.',
  'What this form will be called in the control panel.' => 'Wie dieses Formular im Control Panel genannt wird.',
  'What this integration will be called in the control panel.' => 'Wie diese Integration im Control Panel genannt wird.',
  'What this notification will be called in the control panel.' => 'Wie diese Benachrichtigung im Bedienfeld genannt wird.',
  'What this report will be called in the control panel.' => 'Wie dieser Bericht in der Systemsteuerung heißen soll.',
  'What this scheduled delivery will be called in the control panel.' => 'Wie wird diese geplante Lieferung im Kontrollpanel bezeichnet?',
  'What this status will be called in the control panel.' => 'Wie dieser Status im Control Panel genannt wird.',
  'What this stencil will be called in the control panel.' => 'Wie diese Schablone im Control Panel genannt wird.',
  'What this template will be called in the control panel.' => 'Wie diese Vorlage im Control Panel genannt wird.',
  'What this {entity} will be called in the control panel.' => 'Wie diese {Entität} im Kontrollpanel heißen soll.',
  'When a field has no value and considered "empty", this text will be shown in email notifications.' => 'Wenn ein Feld keinen Wert hat und als "leer" betrachtet wird, wird dieser Text in E-Mail-Benachrichtigungen angezeigt.',
  'When a submission is marked as spam, select what behaviour to perform for users. It’s highly recommended to act as if the submission was successful to prevent parties from learning how to get around the spam protection.' => 'Wenn eine Einreichung als Spam markiert wird, wähle, welches Verhalten den Benutzern gegenüber gezeigt wird. Es wird dringend empfohlen, so zu handeln, als wäre die Einreichung erfolgreich gewesen, um zu verhindern, dass Dritte lernen, wie sie den Spam-Schutz umgehen können.',
  'When a user submits this form, I want to:' => 'Wenn ein Benutzer dieses Formular übermittelt, möchte ich:',
  'When enabled, analytics payloads are emitted in the browser after this page submits successfully.' => 'Wenn diese Option aktiviert ist, werden nach dem erfolgreichen Absenden dieser Seite Analyse-Daten im Browser ausgegeben.',
  'When enabled, each signed download link works only once. Control panel downloads are not affected.' => 'Wenn diese Option aktiviert ist, funktioniert jeder signierte Download-Link nur einmal. Downloads über das Kontrollpanel sind davon nicht betroffen.',
  'When enabled, forms in this group use this palette instead of the global palette from Formie settings.' => 'Wenn diese Option aktiviert ist, verwenden Formulare in dieser Gruppe diese Palette anstelle der globalen Palette aus den Formie-Einstellungen.',
  'When enabled, pasted content is inserted without formatting (for example from Word or websites).' => 'Wenn diese Option aktiviert ist, werden eingefügte Inhalte ohne Formatierung eingefügt (z. B. aus Word oder von Websites).',
  'When enabled, the country sub-field will be pre-filled based on the visitor’s IP address, when no default value is set.' => 'Wenn diese Option aktiviert ist, wird das Unterfeld „Land“ anhand der IP-Adresse des Besuchers automatisch ausgefüllt, sofern kein Standardwert festgelegt ist.',
  'When enabled, the country will be pre-filled based on the visitor’s IP address, when no default value is set.' => 'Wenn diese Option aktiviert ist, wird das Land anhand der IP-Adresse des Besuchers automatisch ausgefüllt, sofern kein Standardwert festgelegt ist.',
  'When enabled, this form appears as its own permission in user group settings. When disabled, access is controlled by global permissions or the form‘s group.' => 'Wenn diese Option aktiviert ist, wird dieses Formular in den Einstellungen der Benutzergruppe als eigene Berechtigung angezeigt. Wenn sie deaktiviert ist, wird der Zugriff über globale Berechtigungen oder die Gruppe des Formulars gesteuert.',
  'When enabled, visitors who return to this form can continue their in-progress submission automatically. Disable this to start fresh unless they use a resume link.' => 'Wenn diese Option aktiviert ist, können Besucher, die zu diesem Formular zurückkehren, ihre bereits begonnene Eingabe automatisch fortsetzen. Deaktivieren Sie diese Option, damit Besucher von vorne beginnen müssen, sofern sie nicht den Link zum Fortsetzen verwenden.',
  'When notifications with the default dispatch timing should be sent. Individual notifications can override this in Advanced settings.' => 'Wann Benachrichtigungen mit dem standardmäßigen Versandzeitpunkt gesendet werden sollen. In den erweiterten Einstellungen können einzelne Benachrichtigungen diese Einstellung überschreiben.',
  'When subdivision data is available, enhance the state/province dropdown with type-to-filter behaviour.' => 'Sobald Daten zu den Untereinheiten vorliegen, soll das Dropdown-Menü für Bundesländer/Provinzen um eine Filterfunktion per Tastatureingabe erweitert werden.',
  'When subdivision data is unavailable and the field falls back to a text input, suggest known subdivisions for the selected country.' => 'Wenn keine Daten zu den Verwaltungsbezirken verfügbar sind und das Feld auf eine Texteingabe zurückfällt, sollen für das ausgewählte Land bekannte Verwaltungsbezirke vorgeschlagen werden.',
  'When to send this notification relative to integrations. Requires Integration Dispatch to be enabled on the form.' => 'Wann diese Benachrichtigung im Zusammenhang mit Integrationen gesendet werden soll. Dazu muss „Integration Dispatch“ im Formular aktiviert sein.',
  'Where the submit button should appear on the page.' => 'Wo die Schaltfläche „Absenden“ auf der Seite erscheinen soll.',
  'Where to position the error message in the form, when shown.' => 'Wo die Fehlermeldung im Formular positioniert werden soll, wenn sie angezeigt wird.',
  'Where to position the success message in the form, when shown.' => 'Wo die Erfolgsmeldung im Formular positioniert werden soll, wenn sie angezeigt wird.',
  'Whether any Email Notifications should be sent.' => 'Ob E-Mail-Benachrichtigungen versendet werden sollen.',
  'Whether any Integrations should be triggered.' => 'Ob Integrationen ausgelöst werden sollen.',
  'Whether clicking the "Back" button on front-end forms should submit the current page content. Disabling this will show an "unload" warning and discard any un-saved content.' => 'Ob beim Klicken auf die Schaltfläche „Zurück“ in Frontend-Formularen der aktuelle Seiteninhalt übermittelt werden soll. Wird diese Option deaktiviert, wird eine Warnung zum „Entladen“ angezeigt und alle nicht gespeicherten Inhalte werden verworfen.',
  'Whether existing user groups should be merged with any set above. Otherwise, any existing user groups will be overwritten.' => 'Ob vorhandene Benutzergruppen mit einem der oben festgelegten Sets zusammengeführt werden sollen. Andernfalls werden vorhandene Benutzergruppen überschrieben.',
  'Whether File Upload fields can use public asset volumes, and whether “Public URL” is available as an email summary value.' => 'Ob Felder für den Datei-Upload öffentliche Asset-Volumes verwenden können und ob „Öffentliche URL“ als Wert in der E-Mail-Zusammenfassung verfügbar ist.',
  'Whether form editors can enable the country code selector on Phone Number fields.' => 'Ob Formular-Editoren die Auswahl des Ländercodes in Feldern für Telefonnummern aktivieren können.',
  'Whether form editors can enable “Allow Multiple” on Dropdown and element fields using a dropdown display type.' => 'Ob Formular-Editoren bei Dropdown- und Elementfeldern mit dem Anzeigetyp „Dropdown“ die Option „Mehrere zulassen“ aktivieren können.',
  'Whether for multi-page forms, the page should automatically scroll to the top of the next page after submission.' => 'Ob bei mehrseitigen Formularen die Seite nach dem Absenden automatisch zum Anfang der nächsten Seite scrollen soll.',
  'Whether front-end forms should trigger an "unload" warning when a form‘s content has changed and the user tries to navigate away without submitting.' => 'Ob Frontend-Formulare eine "unload"-Warnung auslösen sollen, wenn sich der Inhalt eines Formulars geändert hat und der Nutzer versucht, ohne Absenden zu navigieren.',
  'Whether Stripe should email a receipt to the customer on successful payment.' => 'Ob Stripe dem Kunden nach erfolgreicher Zahlung eine Quittung per E-Mail zusenden soll.',
  'Whether submissions marked as spam should still trigger email notifications.' => 'Ob Einsendungen, die als Spam markiert sind, trotzdem E-Mail-Benachrichtigungen auslösen sollen.',
  'Whether tabs of all pages should be included on the page when rendering the form. This is only applicable for forms with more than one page..' => 'Ob beim Rendern des Formulars die Registerkarten aller Seiten auf der Seite angezeigt werden sollen. Dies gilt nur für Formulare mit mehr als einer Seite.',
  'Whether the "Usage" tab in the form builder should include draft elements.' => 'Ob die Registerkarte „Verwendung“ im Formular-Generator Entwurfselemente enthalten soll.',
  'Whether the "Usage" tab in the form builder should include revision elements.' => 'Ob die Registerkarte „Verwendung“ im Formular-Generator Revisionselemente enthalten soll.',
  'Whether the integration should be enabled.' => 'Ob die Integration aktiviert werden soll.',
  'Whether the same user or IP address can submit the quiz more than once.' => 'Ob derselbe Nutzer oder dieselbe IP-Adresse das Quiz mehrmals absolvieren kann.',
  'Whether the title of the current page should be included when rendering the form.' => 'Ob der Titel der aktuellen Seite beim Rendern des Formulars einbezogen werden soll.',
  'Whether the title of this form should be included on the page when rendering the form.' => 'Ob der Titel dieses Formulars auf der Seite angezeigt werden soll, wenn das Formular gerendert wird.',
  'Whether this captcha should be enabled when a new form or stencil is created.' => 'Ob dieses Captcha aktiviert werden soll, wenn ein neues Formular oder eine neue Vorlage erstellt wird.',
  'Whether this field should allow multiple options to be selected.' => 'Ob dieses Feld die Auswahl mehrerer Optionen zulassen soll.',
  'Whether this field should be included when using "All Form Fields", "All Non Empty Fields", or "All Visible Fields" in email notifications.' => 'Ob dieses Feld berücksichtigt werden soll, wenn in E-Mail-Benachrichtigungen die Optionen „Alle Formularfelder“, „Alle nicht leeren Felder“ oder „Alle sichtbaren Felder“ verwendet werden.',
  'Whether this field should be required when filling out the form.' => 'Ob dieses Feld beim Ausfüllen des Formulars erforderlich sein soll.',
  'Whether this field should disallow adding more rows, showing only the default rows.' => 'Ob dieses Feld das Hinzufügen weiterer Zeilen verhindern soll und nur die Standardzeilen anzeigt.',
  'Whether this field should show a "Use my location" button.' => 'Ob dieses Feld eine Schaltfläche "Meinen Standort verwenden" anzeigen soll.',
  'Whether this field should use multiple fields for users to enter their details.' => 'Ob dieses Feld mehrere Felder verwenden soll, damit Benutzer ihre Details eingeben können.',
  'Whether this form can be viewed only by logged-in users.' => 'Ob dieses Formular nur von angemeldeten Benutzern eingesehen werden kann.',
  'Whether this form should collect the users‘ IP address.' => 'Ob dieses Formular die IP-Adresse der Nutzer erfassen soll.',
  'Whether this form should keep a record of the logged-in user.' => 'Ob dieses Formular einen Datensatz des eingeloggten Benutzers behalten soll.',
  'Whether this form should only be available on a schedule.' => 'Ob dieses Formular nur zu einem festgelegten Zeitplan verfügbar sein soll.',
  'Whether this integration should update an existing entry if found, or always create a new entry.' => 'Ob diese Integration einen bestehenden Eintrag aktualisieren soll, falls dieser gefunden wird, oder immer einen neuen Eintrag anlegen soll.',
  'Whether this integration should update an existing event if found, or always create a new event.' => 'Ob diese Integration ein bereits vorhandenes Ereignis aktualisieren soll, falls es gefunden wird, oder immer ein neues Ereignis anlegen soll.',
  'Whether this integration should update an existing product if found, or always create a new product.' => 'Ob diese Integration ein bereits vorhandenes Produkt aktualisieren soll, falls es gefunden wird, oder immer ein neues Produkt anlegen soll.',
  'Whether this integration should update an existing user if found, or always create a new user.' => 'Ob bei dieser Integration ein bereits vorhandener Benutzer aktualisiert werden soll, falls er gefunden wird, oder ob immer ein neuer Benutzer angelegt werden soll.',
  'Whether this integration should update the search indexes to include content for this element.' => 'Ob bei dieser Integration die Suchindizes aktualisiert werden sollen, um Inhalte für dieses Element einzubeziehen.',
  'Whether this notification is enabled to send.' => 'Ob diese Benachrichtigung aktiviert ist, um gesendet zu werden.',
  'Whether this scheduled delivery should run and send emails.' => 'Ob diese geplante Zustellung ausgeführt und E-Mails versendet werden soll.',
  'Whether this status should be used as the default for new submissions.' => 'Ob dieser Status als Standard für neue Einreichungen verwendet werden soll.',
  'Whether to activate the user automatically.' => 'Ob der Benutzer automatisch aktiviert werden soll.',
  'Whether to add an additional checkbox to toggle all checkboxes in this field by.' => 'Ob ein zusätzliches Kontrollkästchen hinzugefügt werden soll, um alle Kontrollkästchen in diesem Feld umzuschalten.',
  'Whether to append tags to the list of existing member tags.' => 'Ob Tags an die Liste vorhandener Mitgliedertags angehängt werden sollen.',
  'Whether to attach a PDF template to this email notification.' => 'Ob an diese E-Mail-Benachrichtigung eine PDF-Vorlage angehängt werden soll.',
  'Whether to attach file uploads to this email notification.' => 'Ob Datei-Uploads an diese E-Mail-Benachrichtigung angehängt werden sollen.',
  'Whether to block email addresses from free email providers like `gmail.com` or `hotmail.com`.' => 'Ob E-Mail-Adressen von kostenlosen E-Mail-Anbietern wie `gmail.com` oder `hotmail.com` blockiert werden sollen.',
  'Whether to continue running later integrations when one fails.' => 'Ob spätere Integrationen fortgesetzt werden sollen, wenn eine davon fehlschlägt.',
  'Whether to create a new draft entry. If an existing entry is found, a new draft will be created on the original entry, instead of updating the existing entry.' => 'Ob ein neuer Entwurf erstellt werden soll. Wird ein bestehender Eintrag gefunden, wird auf Basis des ursprünglichen Eintrags ein neuer Entwurf erstellt, anstatt den bestehenden Eintrag zu aktualisieren.',
  'Whether to create a task on duplicate lead detected errors.' => 'Soll bei der Erkennung von doppelten Leads eine Aufgabe erstellt werden?',
  'Whether to disable the submit button until the current page passes validation. This can help users identify missing required fields before submitting.' => 'Ob die Schaltfläche „Absenden“ deaktiviert werden soll, bis die aktuelle Seite die Validierung bestanden hat. Dies kann den Benutzern helfen, fehlende Pflichtfelder vor dem Absenden zu erkennen.',
  'Whether to display this field with a rich text editor for users to enter values with.' => 'Ob dieses Feld mit einem Rich-Text-Editor angezeigt werden soll, über den Benutzer Werte eingeben können.',
  'Whether to enable conditional logic to control how the next button is shown.' => 'Ob eine bedingte Logik aktiviert werden soll, um zu steuern, wie die Schaltfläche „Weiter“ angezeigt wird.',
  'Whether to enable conditional logic to control how this email notification is sent.' => 'Ob bedingte Logik aktiviert werden soll, um zu steuern, wie diese E-Mail-Benachrichtigung gesendet wird.',
  'Whether to enable conditional logic to control how this field is shown.' => 'Ob bedingte Logik aktiviert werden soll, um zu steuern, wie dieses Feld angezeigt wird.',
  'Whether to enable conditional logic to control how this page is shown.' => 'Ob bedingte Logik aktiviert werden soll, um die Darstellung dieser Seite zu steuern.',
  'Whether to enable conditional logic to control when this client event is pushed.' => 'Ob eine bedingte Logik aktiviert werden soll, um zu steuern, wann dieses Client-Ereignis gesendet wird.',
  'Whether to enable conditional logic to control when this integration is triggered.' => 'Ob bedingte Logik aktiviert werden soll, um zu steuern, wann diese Integration ausgelöst wird.',
  'Whether to enable conditional logic to control when this status rule is applied.' => 'Ob bedingte Logik aktiviert werden soll, um zu steuern, wann diese Statusregel angewendet wird.',
  'Whether to enable Craft‘s CSRF validation checks for anonymous form submissions.' => 'Ob Craft‘s CSRF-Validierungsprüfungen für anonyme Formularübermittlungen aktiviert werden sollen.',
  'Whether to enable saving email notifications as sent notifications.' => 'Ob das Speichern von E-Mail-Benachrichtigungen als versendete Benachrichtigungen aktiviert werden soll.',
  'Whether to enable this integration.' => 'Ob diese Integration aktiviert werden soll.',
  'Whether to encrypt the value saved for this field for data-security purposes.' => 'Ob der für dieses Feld gespeicherte Wert aus Gründen der Datensicherheit verschlüsselt werden soll.',
  'Whether to hide the card icon, shown alongside credit card number fields.' => 'Ob das Kartensymbol, das neben den Feldern für die Kreditkartennummer angezeigt wird, ausgeblendet werden soll.',
  'Whether to hide the form and only show the success message.' => 'Ob das Formular versteckt und nur die Erfolgsmeldung angezeigt werden soll.',
  'Whether to hide the zip/postal code field, shown alongside credit card number fields.' => 'Ob das Feld für die Postleitzahl, das neben den Feldern für die Kreditkartennummer angezeigt wird, ausgeblendet werden soll.',
  'Whether to limit the numbers for this field.' => 'Ob die Zahlen für dieses Feld begrenzt werden sollen.',
  'Whether to limit the options users can choose for this field.' => 'Ob die Auswahlmöglichkeiten, die Benutzer für dieses Feld wählen können, eingeschränkt werden sollen.',
  'Whether to limit the value of this field.' => 'Ob der Wert dieses Feldes begrenzt werden soll.',
  'Whether to limit user input to unique values only. This will require that a value entered in this field does not already exist in a submission for this field and form.' => 'Ob die Benutzereingabe nur auf eindeutige Werte beschränkt werden soll. Dies erfordert, dass ein Wert, der in dieses Feld eingegeben wird, noch nicht in einer Einreichung für dieses Feld und Formular vorhanden ist.',
  'Whether to map file-upload fields to attachments in Salesforce.' => 'Ob Dateiupload-Felder in Salesforce Anhängen zugeordnet werden sollen.',
  'Whether to map form data to {name} {label}.' => 'Ob Formulardaten {name} {label} zugeordnet werden sollen.',
  'Whether to overwrite existing content, even if empty values are provided.' => 'Ob vorhandene Inhalte überschrieben werden sollen, auch wenn leere Werte angegeben werden.',
  'Whether to parse Twig in this field’s content when rendering the form. Twig is evaluated in Formie’s sandbox and cannot access Craft’s full template environment.' => 'Gibt an, ob der Inhalt dieses Feldes beim Rendern des Formulars mit Twig geparst werden soll. Twig wird in der Sandbox von Formie ausgewertet und hat keinen Zugriff auf die vollständige Template-Umgebung von Craft.',
  'Whether to proxy the redirect URI through Verbb‘s servers. This should **only** be used for local testing. See {link} for more.' => 'Ob die Umleitungs-URI über die Server von Verbb weitergeleitet werden soll. Diese Option sollte **nur** für lokale Tests verwendet werden. Weitere Informationen finden Sie unter {link}.',
  'Whether to reload the page when this form is submitted, or use Ajax to send this form without reloading the page.' => 'Ob die Seite neu geladen werden soll, wenn dieses Formular übermittelt wird, oder Ajax verwenden, um dieses Formular ohne Neuladen der Seite zu senden.',
  'Whether to restrict the allowed types of files a user can upload.' => 'Ob die zulässigen Dateitypen, die ein Benutzer hochladen darf, eingeschränkt werden sollen.',
  'Whether to run [HTML Purifier](http://htmlpurifier.org) over the content to prevent malicious or invalid code being included.' => 'Ob [HTML Purifier](http://htmlpurifier.org) auf den Inhalt angewendet werden soll, um zu verhindern, dass bösartiger oder ungültiger Code eingebunden wird.',
  'Whether to save spam submissions, so they can be viewed in the control panel. Otherwise, spam submissions will be discarded.' => 'Ob Spam-Einreichungen gespeichert werden sollen, damit sie im Control Panel eingesehen werden können. Andernfalls werden Spam-Einreichungen verworfen.',
  'Whether to send an email campaign to the created contact.' => 'Ob eine E-Mail-Kampagne an den angelegten Kontakt gesendet werden soll.',
  'Whether to send billing details alongside the payment.' => 'Ob die Rechnungsdaten zusammen mit der Zahlung übermittelt werden sollen.',
  'Whether to send the activation email for the user automatically.' => 'Ob die Aktivierungsemail für den Benutzer automatisch gesendet werden soll.',
  'Whether to show a loading indicator when submitting the form. This will be shown on the submit button.' => 'Ob ein Ladeindikator beim Absenden des Formulars angezeigt werden soll. Dies wird auf dem Absenden-Button angezeigt.',
  'Whether to show a progress bar of the page completion. This is only applicable for forms with more than one page.' => 'Ob eine Fortschrittsanzeige des Seitenabschlusses gezeigt werden soll. Dies gilt nur für Formulare mit mehr als einer Seite.',
  'Whether to show a tagline underneath buttons.' => 'Ob unter den Schaltflächen ein Slogan angezeigt werden soll.',
  'Whether to show the back button, to go back to a previous page.' => 'Ob die Zurück-Schaltfläche angezeigt werden soll, um zur vorherigen Seite zurückzukehren.',
  'Whether to show the dial code on the country dropdown.' => 'Ob die Ländervorwahl im Länder-Dropdown angezeigt werden soll.',
  'Whether to show the hierarchical structure of categories in the dropdown.' => 'Ob die hierarchische Struktur von Kategorien im Dropdown-Menü angezeigt werden soll.',
  'Whether to show the save button, allowing users to save progress on a submission to return later.' => 'Ob die Schaltfläche „Speichern“ angezeigt werden soll, damit Benutzer den Fortschritt einer Eingabe speichern und später darauf zurückkommen können.',
  'Whether to submit this form data to your Pardot form handler endpoint.' => 'Ob die Daten dieses Formulars an den Endpunkt Ihres Pardot-Formularhandlers übermittelt werden sollen.',
  'Whether to use Craft‘s queue system to trigger emails. This is highly recommended to prevent slow submissions for your users.' => 'Ob das Warteschlangensystem von Craft verwendet werden soll, um E-Mails auszulösen. Dies wird dringend empfohlen, um langsame Einreichungen für deine Nutzer zu verhindern.',
  'Whether to use Craft‘s queue system to trigger integrations. This is highly recommended to prevent slow submissions for your users.' => 'Ob das Warteschlangensystem von Craft verwendet werden soll, um Integrationen auszulösen. Dies wird dringend empfohlen, um langsame Einreichungen für deine Nutzer zu verhindern.',
  'Whether to use double opt-in, which will send the user a confirmation email before they‘re added to the list.' => 'Ob das Double-Opt-in verwendet werden soll, bei dem dem Nutzer eine Bestätigungs-E-Mail gesendet wird, bevor er in die Liste aufgenommen wird.',
  'Whether to use the {name} developer API. Only use this for specific {name} developer accounts.' => 'Ob die {name}-Entwickler-API verwendet werden soll. Verwenden Sie diese nur für bestimmte {name}-Entwicklerkonten.',
  'Whether to use the {name} sandbox.' => 'Ob die {name} Sandbox verwendet werden soll.',
  'Whether to use the {name} UAT for testing.' => 'Ob das {name} UAT zum Testen verwendet werden soll.',
  'Whether to use the {name} username/password credentials.' => 'Ob die Anmeldedaten {name} (Benutzername/Passwort) verwendet werden sollen.',
  'Whether to validate each field as the user types, so that errors will appear immediately.' => 'Ob jedes Feld validiert werden soll, während der Benutzer tippt, sodass Fehler sofort erscheinen.',
  'Whether to validate the domain name provided for the email via DNS record lookup. This can help ensure users enter valid email addresses.' => 'Ob der Domänenname für die E-Mail über DNS-Abfrage validiert werden soll. Dies kann dazu beitragen, dass Benutzer gültige E-Mail-Adressen eingeben.',
  'Whether to validate the form client-side, when the user submits the form. This will show errors as soon as the submit button is pressed. Forms will also always be validated server-side.' => 'Ob das Formular auf der Client-Seite validiert werden soll, wenn der Benutzer das Formular übermittelt. Dies wird Fehler anzeigen, sobald der Absenden-Button gedrückt wird. Formulare werden auch immer serverseitig validiert.',
  'Which day of the week this delivery should run. Only used for weekly schedules.' => 'An welchem Wochentag diese Lieferung stattfinden soll. Wird nur für wöchentliche Zeitpläne verwendet.',
  'Which source do you want to select categories from?' => 'Aus welcher Quelle möchten Sie Kategorien auswählen?',
  'Which source do you want to select tags from?' => 'Aus welcher Quelle möchtest du Tags auswählen?',
  'Which source do you want to select variants from?' => 'Aus welcher Quelle möchten Sie Varianten auswählen?',
  'Which sources do you want to select entries from?' => 'Aus welchen Quellen möchtest du Einträge auswählen?',
  'Which sources do you want to select products from?' => 'Aus welchen Quellen möchten Sie Produkte auswählen?',
  'Which sources do you want to select users from?' => 'Aus welchen Quellen möchten Sie Benutzer auswählen?',
  'White' => 'Weiß',
  'Widget Mode' => 'Widget-Modus',
  'Widget Options' => 'Widget-Optionen',
  'Widowed' => 'Verwitwet',
  'Width' => 'Breite',
  'Win Probability' => 'Gewinnwahrscheinlichkeit',
  'Won' => 'Gewonnen',
  'Words' => 'Wörter',
  'Work Number' => 'Arbeitsnummer',
  'Workspace ID' => 'Arbeitsbereichs-ID',
  'Workspace Users' => 'Arbeitsbereich-Benutzer',
  'Would You' => 'Würden Sie',
  'XLSX export requires Craft CMS 5.9 or later.' => 'Für den XLSX-Export ist Craft CMS 5.9 oder höher erforderlich.',
  'XML' => 'XML',
  'Year' => 'Jahr',
  'Year Range' => 'Jahreszeitraum',
  'Years' => 'Jahre',
  'Years in Business' => 'Jahre im Geschäft',
  'Yes' => 'Ja',
  'Yet To Start' => 'Noch nicht begonnen',
  'You are about to resend {desc}. You can resend each notification to their original recipients, or choose specific recipients.' => 'Du bist dabei, {desc} erneut zu senden. Du kannst jede Benachrichtigung erneut an ihre ursprünglichen Empfänger senden oder spezifische Empfänger auswählen.',
  'You have already completed this quiz.' => 'Sie haben dieses Quiz bereits absolviert.',
  'You must be logged in to submit this form.' => 'Du musst angemeldet sein, um dieses Formular einzureichen.',
  'You must save your form before sending a test payload.' => 'Du musst dein Formular speichern, bevor du Testdaten sendest.',
